INSERT INTO `blog_posts` (`id`,`title`,`slug`,`category`,`excerpt`,`body`,`image`,`author`,`tags`,`status`,`views`,`published_at`) VALUES
(1,'Routine skincare : les 5 étapes essentielles','routine-skincare-les-5-etapes-essentielles','Soins','Découvrez nos conseils d''experts pour routine skincare : les 5 étapes essentielles et sublimer votre beauté au quotidien.','<p>Chez Bella Rosa, nous croyons que la beauté commence par des gestes simples et des produits d''exception. Dans cet article, notre équipe partage ses conseils d''experts pour sublimer votre routine au quotidien.</p><h2>Nos recommandations</h2><p>Adoptez des soins adaptés à votre type de peau et privilégiez la régularité. La constance est la clé de résultats visibles et durables.</p><ul><li>Nettoyez matin et soir en douceur.</li><li>Hydratez avec des actifs ciblés.</li><li>Protégez votre peau des agressions extérieures.</li></ul><h2>Le mot de la fin</h2><p>Prenez le temps de vous chouchouter : votre peau vous le rendra. Découvrez notre sélection pour composer le rituel qui vous ressemble.</p>','blog-01.jpg','Sarah M.','Soins, beauté, conseils','published',4265,'2026-08-07 08:39:59'),
